    if (eclipse != NULL) *eclipse = 0;
    if (behind_m != NULL) *behind_m = 0.0;
    if (miss_m != NULL) *miss_m = INFINITY;
    return ADCS_E_RANGE;
}

// Validate finiteness of input vectors and radius
if (!adcs_is_finite_vec3(position_m) || !adcs_is_finite_vec3(sun_direction) || !isfinite(earth_radius_m)) {
    if (eclipse != NULL) *eclipse = 0;
    if (behind_m != NULL) *behind_m = 0.0;
    if (miss_m != NULL) *miss_m = INFINITY;
    return ADCS_E_RANGE;
}

// Normalize sun direction
adcs_vec3_t s;
adcs_status_t norm_status = adcs_vec3_normalize(sun_direction, 0.0, &s);
if (norm_status != ADCS_OK) {
    // Degenerate or other normalization failure maps to ADCS_E_RANGE per requirement
    if (eclipse != NULL) *eclipse = 0;
    if (behind_m != NULL) *behind_m = 0.0;
    if (miss_m != NULL) *miss_m = INFINITY;
    return ADCS_E_RANGE;
}

// Compute projection behind Earth: behind = -position dot s
double behind_val = -adcs_vec3_dot(position_m, &s);

