adcs_vec3_t scaled_s = adcs_vec3_scale(&s, behind_val);
adcs_vec3_t miss_vector = adcs_vec3_add(position_m, &scaled_s);

// Compute miss distance: miss = ||miss_vector||
double miss_val = adcs_vec3_norm(&miss_vector);

// Determine eclipse flag: behind > 0 AND miss < earth_radius
int eclipse_flag = (behind_val > 0.0) && (miss_val < earth_radius_m);

// Write outputs
if (behind_m != NULL) *behind_m = behind_val;
if (miss_m != NULL) *miss_m = miss_val;
if (eclipse != NULL) *eclipse = eclipse_flag;

return ADCS_OK;

