// 1. Input validation: Check for NULL pointers
if ((position_m == NULL) || (sun_direction == NULL) || 
    (eclipse == NULL) || (behind_m == NULL) || (miss_m == NULL)) {
    *eclipse = 0;
    *behind_m = 0.0;
    *miss_m = INFINITY;
    return ADCS_E_NULL;
}

// 2. Check for nonpositive radius
if (earth_radius_m <= 0.0) {
    *eclipse = 0;
    *behind_m = 0.0;
    *miss_m = INFINITY;
    return ADCS_E_RANGE;
}

// 3. Check for nonfinite data
if ((!adcs_is_finite_vec3(position_m)) || (!adcs_is_finite_vec3(sun_direction))) {
    *eclipse = 0;
    *behind_m = 0.0;
    *miss_m = INFINITY;
    return ADCS_E_NOT_FINITE;
}

// 4. Normalize Sun direction to get unit vector s
adcs_vec3_t s;
adcs_status_t norm_status = adcs_vec3_normalize(sun_direction, 0.0, &s);
if (norm_status != ADCS_OK) {
    // Degenerate case: zero length sun direction or other normalization failure
    *eclipse = 0;
    *behind_m = 0.0;
    *miss_m = INFINITY;
    return ADCS_E_DEGENERATE;
}

// 5. Compute behind = -position dot s
double behind_val = -adcs_vec3_dot(position_m, &s);

// 6. Compute miss_vector = position + behind * s
adcs_vec3_t scaled_s = adcs_vec3_scale(&s, behind_val);
adcs_vec3_t miss_vector = adcs_vec3_add(position_m, &scaled_s);

// 7. Compute miss = ||miss_vector||
double miss_val = adcs_vec3_norm(&miss_vector);

// 8. Determine eclipse flag: (behind > 0) && (miss < earth_radius)
// Strict inequality for radius equality means sunlight
int eclipse_flag = (behind_val > 0.0) && (miss_val < earth_radius_m) ? 1 : 0;

// 9. Assign output values
*behind_m = behind_val;
*miss_m = miss_val;
*eclipse = eclipse_flag;

return ADCS_OK;

